import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.BSaF8iZ6.js";const g=JSON.parse('{"title":"Commission","description":"","frontmatter":{},"headers":[],"relativePath":"payments/commission-management.md","filePath":"payments/commission-management.md","lastUpdated":1789411447000}'),a={name:"payments/commission-management.md"};function r(i,e,l,h,m,d){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="commission" tabindex="-1">Commission <a class="header-anchor" href="#commission" aria-label="Permalink to &quot;Commission&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span><span class="role role--seller">Seller</span></div><p>Commission is the share of each seller sale the store keeps. The seller is paid the rest. The rate is fixed on each order when it is placed.</p><h2 id="which-rate-applies" tabindex="-1">Which rate applies <a class="header-anchor" href="#which-rate-applies" aria-label="Permalink to &quot;Which rate applies&quot;">​</a></h2><p>A seller&#39;s sales use the first of these that applies:</p><ol><li><strong>The seller&#39;s own rate</strong>, when the admin has switched <strong>Commission Enabled</strong> on for the seller and set a <strong>Commission Percentage</strong>.</li><li><strong>The store&#39;s rate</strong>, the <strong>Admin Commission Percentage</strong> for the channel the order is placed on.</li></ol><p>A subscription plan sets the seller&#39;s own rate to the plan&#39;s <strong>Commission Value</strong> when the plan becomes active. Always enter a <strong>Commission Value</strong> on a plan: a plan without one leaves the seller paying no commission while it is active. Commission can&#39;t be set per category or per product.</p><h2 id="set-the-store-s-rate" tabindex="-1">Set the store&#39;s rate <a class="header-anchor" href="#set-the-store-s-rate" aria-label="Permalink to &quot;Set the store&#39;s rate&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Marketplace &gt;&gt; General</strong>.</li><li>Enter the <strong>Admin Commission Percentage</strong>, between 1 and 100.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The rate can be set for each channel, and each order uses the rate of its channel. See <a href="./../configuration/general">General settings</a>.</p><h2 id="set-a-rate-for-one-seller" tabindex="-1">Set a rate for one seller <a class="header-anchor" href="#set-a-rate-for-one-seller" aria-label="Permalink to &quot;Set a rate for one seller&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers</strong> and click the edit icon on the seller.</li><li>In <strong>Settings</strong>, switch <strong>Commission Enabled</strong> on.</li><li>Enter the <strong>Commission Percentage</strong>.</li><li>Click <strong>Save Seller</strong>.</li></ol><p>See <a href="./../sellers/seller-management#settings-for-this-seller">Seller Management</a>.</p><h2 id="how-commission-is-worked-out" tabindex="-1">How commission is worked out <a class="header-anchor" href="#how-commission-is-worked-out" aria-label="Permalink to &quot;How commission is worked out&quot;">​</a></h2><p>For each product in the order:</p><ul><li><strong>Commission</strong> = (the product&#39;s total − its discount) × the rate</li><li><strong>Seller earning</strong> = the product&#39;s total − its discount − commission + tax</li></ul><table tabindex="0"><thead><tr><th>Example</th><th>Amount</th></tr></thead><tbody><tr><td>Product total</td><td>$100.00</td></tr><tr><td>Discount</td><td>−$10.00</td></tr><tr><td>Commission at 20% of $90.00</td><td>−$18.00</td></tr><tr><td>Tax</td><td>+$5.00</td></tr><tr><td><strong>Seller earning</strong></td><td><strong>$77.00</strong></td></tr></tbody></table><ul><li>The rate in force when the order is placed stays with that order, even if the rate changes later.</li><li>Commission is worked out again on what is actually invoiced, and that is the amount the seller is paid.</li><li>Shipping isn&#39;t part of the commission or the seller&#39;s earning.</li><li>A refund doesn&#39;t change the commission. Any refund on an order, even a partial one, sets its <strong>Seller Payment Status</strong> to <strong>Refunded</strong>, and the seller can&#39;t request payment for it. See <a href="./payment-management">Payment Requests &amp; Payouts</a>.</li></ul><h2 id="where-commission-shows" tabindex="-1">Where commission shows <a class="header-anchor" href="#where-commission-shows" aria-label="Permalink to &quot;Where commission shows&quot;">​</a></h2><ul><li>Sellers see their rate on <strong>My Profile</strong>, as <strong>Admin Commission … of total Invoiced Amount</strong>.</li><li>The <strong>Commission</strong> and <strong>Seller Earn</strong> columns on the seller&#39;s orders, and <strong>Admin Commission</strong> on each order.</li><li><strong>Total Commission (Admin)</strong> on the seller&#39;s <a href="./transactions">Transactions</a> page, and <strong>Total Commission Paid</strong> in their <a href="./../reporting/seller-reporting">reports</a>.</li><li>The <strong>Commission</strong> column on the admin&#39;s <strong>Marketplace &gt;&gt; Sales &gt;&gt; Orders</strong>, and the commission figures on each transaction the admin opens.</li><li><strong>Total Commission Earned</strong> on the admin&#39;s <a href="./payment-management">Payment Requests</a> page.</li></ul><h2 id="when-a-subscription-plan-expires" tabindex="-1">When a subscription plan expires <a class="header-anchor" href="#when-a-subscription-plan-expires" aria-label="Permalink to &quot;When a subscription plan expires&quot;">​</a></h2><p>If a seller&#39;s plan expires without another active plan, the seller&#39;s commission becomes 100% until they buy a new plan. This also happens if the store has since switched subscriptions off. If the admin cancels a plan instead, the seller keeps the plan&#39;s rate. See <a href="./../subscriptions/choosing-a-plan">Choosing a Plan</a>.</p>',22)])])}const p=t(a,[["render",r]]);export{g as __pageData,p as default};
